describe('Icon Button Accessibility', () => {
  beforeEach(() => {
    cy.visit('/icon-buttons');
  });

  it('should display accessible names for all icon buttons', () => {
    cy.get('[data-testid="icon-button-home"]').should('be.visible');
    cy.get('[data-testid="icon-button-home"]').should('have.attr', 'aria-label', 'Go to Home');

    cy.get('[data-testid="icon-button-settings"]').should('be.visible');
    cy.get('[data-testid="icon-button-settings"]').should('have.attr', 'aria-label', 'Open Settings');

    cy.get('[data-testid="icon-button-help"]').should('be.visible');
    cy.get('[data-testid="icon-button-help"]').should('have.attr', 'aria-label', 'Get Help');

    cy.get('[data-testid="icon-button-logout"]').should('be.visible');
    cy.get('[data-testid="icon-button-logout"]').should('have.attr', 'aria-label', 'Logout');
  });

  it('should handle icon button with no visible text', () => {
    cy.get('[data-testid="icon-button-search"]').should('be.visible');
    cy.get('[data-testid="icon-button-search"]').should('have.attr', 'aria-label', 'Search');

    cy.get('[data-testid="icon-button-settings"]').should('be.visible');
    cy.get('[data-testid="icon-button-settings"]').should('have.attr', 'aria-label', 'Open Settings');

    cy.get('[data-testid="icon-button-help"]').should('be.visible');
    cy.get('[data-testid="icon-button-help"]').should('have.attr', 'aria-label', 'Get Help');

    cy.get('[data-testid="icon-button-logout"]').should('be.visible');
    cy.get('[data-testid="icon-button-logout"]').should('have.attr', 'aria-label', 'Logout');

    // Verify that the button with no visible text has an appropriate aria-label
    cy.get('[data-testid="icon-button-search"]').should('have.attr', 'aria-label', 'Search');
  });
});
